

import 'dart:typed_data';

import 'package:dartsv/dartsv.dart';

class PP2LockBuilder extends LockingScriptBuilder{

  //debug_template
  String template = "0176018801a901ac5101402097dfd76851bf465e8f715593b217714858bbe9570ff3bd5e33840a34e20ff0262102ba79df5f8ae7604a9830f03c7933028186aede0675a16f025dc4f8be8eec0382201008ce7480da41702918d1ec8e6849ba32b4d65b1e40dc669c31a1e6306b266c000000<outpoint><witnessChangePKH><witnessChangeAmount>";

  //release_template
  // String template = "";

  final List<int> _changeOutpoint;
  final List<int> _witnessChangePKH;
  final int _changeAmount;

  PP2LockBuilder(this._changeOutpoint, this._witnessChangePKH, this._changeAmount);

  @override
  SVScript getScriptPubkey() {

    var scriptHex = template
        .replaceFirst("<outpoint>", ScriptBuilder().addData(Uint8List.fromList(_changeOutpoint)).build().toHex())
        .replaceFirst("<witnessChangePKH>", ScriptBuilder().addData(Uint8List.fromList(_witnessChangePKH)).build().toHex())
        .replaceFirst("<witnessChangeAmount>", ScriptBuilder().number(_changeAmount).build().toHex()) ;

        return SVScript.fromHex(scriptHex);
  }

  @override
  void parse(SVScript script) {
    // TODO: implement parse
  }}